{{ af.field({'label': l.username ?? '', 'for': id ~ '-username', 'formError': formError, 'describe': (l.domain ?? '') ? id ~ '-domain' : null, 'suffix': c1, 'input': {'type': 'text', 'name': 'username', 'required': true, 'attrs': {'autocomplete': 'username'}}}) }}
{{ af.field({'label': l.password ?? '', 'for': id ~ '-password', 'hint': l.hint ?? '', 'formError': formError, 'input': {'type': 'password', 'name': 'password', 'required': true, 'attrs': {'autocomplete': 'new-password'}}}) }}
{%- if (p.terms ?? 'show') == 'show' -%}
{%- set c2 -%}{{ include('ui/checkbox/Checkbox.html.twig', {name: 'terms', required: true, id: id ~ '-terms', ariaDescribedBy: formError, ariaInvalid: formError ? 'true' : null, class: af_skin('checkbox')}, with_context = false) }}{{- include('ui/label/Label.html.twig', {htmlFor: id ~ '-terms', class: af_skin('label', 'font-normal'), children: af_esc(l.terms ?? '')}, with_context = false) }}{%- endset -%}
{{ af.group('2', '', '', 'w-fit', {}, c2) }}
{%- endif -%}
{{ af.button('', 'submit', af_skin('button', 'default', 'w-full'), {'data-testid': 'submit'}, af_esc(l.submit ?? '')) }}{%- endset -%}
{{ af.form(p.action ?? '', '', {'data-testid': 'authfly-form'}, c3) }}
{%- if l.signinLink ?? '' -%}
{%- set c4 -%}{{ l.signinText ?? '' }} {{ af.link(l.signinHref ?? '', af_skin('link'), 'signin-link', l.signinLink ?? '') }}{%- endset -%}
{{ af.text('', af_text('muted'), {}, c4) }}
{%- endif -%}
